import{_ as a,c as n,a as p,o as i}from"./app-D4Z08XdH.js";const r={};function d(c,e){return i(),n("div",null,e[0]||(e[0]=[p('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-25-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-25-资讯日报"><span>2026-11-25 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="openai首席科学家公布模型困惑度" tabindex="-1"><a class="header-anchor" href="#openai首席科学家公布模型困惑度"><span>OpenAI首席科学家公布模型困惑度</span></a></h3><p>OpenAI 首席科学家公开核心指标困惑度，透露 GPT-3.5 约为 0.99、GPT-4 约为 0.91，最新模型已低于 0.8。</p><p>建议全行业据此设上限，达安全监控标准再推进</p><p>0.76时数学出突破，下一个关键窗口是0.68至0.7</p><p>AI已参与模型设计，2027年预训练或迎雪崩式进展<a href="https://mp.weixin.qq.com/s?__biz=MzIwOTA1MDAyNA==&amp;chksm=8e63222feee8b4c92000947fae6208256a2e6628fa2dd62348b0a8a541cd70fdc8d65dfa1433&amp;idx=2&amp;mid=2650058000&amp;sn=37aa2c4b6e83ae23a28bc34fb05ccfbf" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="minimax模型破译密码速度提升4万倍" tabindex="-1"><a class="header-anchor" href="#minimax模型破译密码速度提升4万倍"><span>MiniMax模型破译密码速度提升4万倍</span></a></h3><p>MiniMax 展示其内部模型 MIM 在密码分析上的成果：在国际抗量子密码挑战中全球首次攻破 55 个未解私钥，破译速度最高提升 43400 倍至最快 1.8 秒。</p><p>悬案攻克：3.5毫秒内破解悬置18年的哈希算法</p><p>算力压缩：将后量子加密破译内存从42PB降至58MB</p><p>代码排查：在多套官方候选算法源码中挑出十余处漏洞<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=91222ec54327d0f63670c7c4848df65acd9d5db9f7191ccbd32ddda74d44b52e30ea37313634&amp;idx=1&amp;mid=2247749897&amp;sn=b86f43390a097ba86b3605951834a5b5" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="马斯克称-optimus-18-个月内能洗碗" tabindex="-1"><a class="header-anchor" href="#马斯克称-optimus-18-个月内能洗碗"><span>马斯克称 Optimus 18 个月内能洗碗</span></a></h3><p>马斯克在活动中称，特斯拉人形机器人 Optimus 将在 12 到 18 个月内 做到倒垃圾、洗碗并放回橱柜，并计划在一两个月内做一次无预编程的真实演示。</p><p>技术重构：xAI正用C和C++从零重写训练和推理技术栈</p><p>落地场景：机器人早期最有价值的场景是采矿等重工业</p><p>算力扩张：目前每月新增约半吉瓦算力对应22万块GB300<a href="https://mp.weixin.qq.com/s?__biz=Mzg4NDQwNTI0OQ==&amp;chksm=cee5b12bdc87a9db6047377e68d10176407ce6b8fc8dd60232e3c11427e7086c0d65a3148620&amp;idx=1&amp;mid=2247591155&amp;sn=0f78b6b0ba3f6c90e4bab71d60ec7d9a" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="sand-ai发布magi-2-1080p每秒0-5元" tabindex="-1"><a class="header-anchor" href="#sand-ai发布magi-2-1080p每秒0-5元"><span>Sand.ai发布MAGI-2：1080P每秒0.5元</span></a></h3><p>Sand.ai 发布 480B 全模态视频模型 MAGI-2，最长支持 30 秒生成与 20 个素材参考。其 1080P 生成价格为每秒 0.5 元，现已上线 LibTV，后续计划开源。</p><p>性能对比：运镜与物理遵循良好，画质略逊且音频 AI 味重</p><p>功能规格：单次支持 20 个图音视素材参考与局部编辑</p><p>后续规划：官方表示该模型未来将直接开源<a href="https://mp.weixin.qq.com/s?__biz=MzIyMzA5NjEyMA==&amp;chksm=f19a674dcc5321ab3010016e48400567392b7d3490174539cae91395def14ffef6872c8eac0d&amp;idx=1&amp;mid=2647688752&amp;sn=9206be14f4d0dc96f515c91049063ab9" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="小鹏发布x-world-1-6世界模型" tabindex="-1"><a class="header-anchor" href="#小鹏发布x-world-1-6世界模型"><span>小鹏发布X-World 1.6世界模型</span></a></h3><p>小鹏发布自动驾驶世界模型 X-World 1.6，引入真实道路参考以稳定复现建筑等静态环境，将人工操控仿真延迟缩短至 426 毫秒，轨迹终点误差降低 20.9%。</p><p>静态控制：引入3D高斯与点云约束背景，动态部分由DiT生成</p><p>交互测试：支持超30秒连续生成，可接方向盘与踏板实时驾驶</p><p>数据规模：候选记录池扩大到4倍，训练数据集规模扩大2倍<a href="https://mp.weixin.qq.com/s?__biz=MzUyODY1NDE1NA==&amp;chksm=fbafcfb33ff7a7b1989a90a939cfd434b4559c629c9c81e5168ec9e4464b4ab84073c0088ccb&amp;idx=1&amp;mid=2247579158&amp;sn=cf9ebd8a51ebdda0d887d3af5618f143" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="anthropic更新mcp支持技能与长任务" tabindex="-1"><a class="header-anchor" href="#anthropic更新mcp支持技能与长任务"><span>Anthropic更新MCP支持技能与长任务</span></a></h3><p>Anthropic更新工具连接协议MCP，Skills技能扩展进入公测，支持后台异步执行长任务的Tasks以及要求用户确认操作的Elicitation正式可用。</p><p>文件直传：即将支持文件不经上下文直接发往服务器</p><p>生态规模：月SDK下载超7亿次且连接器超1万个</p><p>上下文优化：按需搜索加载让多服务器占用减少超85%<a href="https://mp.weixin.qq.com/s?__biz=MzA5MTIxNTY4MQ==&amp;chksm=864dfb89d9b054db2b8e2ffc8fd4574822d72921d953a19646344f9984e5389a9dc23ea49f11&amp;idx=1&amp;mid=2461162105&amp;sn=ddb4ffe145ce561bfc542c8982544570" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="snowflake推决策ai-百万token-4-2美分" tabindex="-1"><a class="header-anchor" href="#snowflake推决策ai-百万token-4-2美分"><span>Snowflake推决策AI：百万Token 4.2美分</span></a></h3><p>Snowflake 推出专门用于分类、评分和条件判断的模型 Snowflake Decision 并开启公测，支持直接用 SQL 批量处理，价格低至每百万 Token 0.042 美元。</p><p>机制：单次请求最多可对同一输入连做64个独立判断</p><p>性能：单行处理约1.58毫秒，直接嵌入SQL批处理</p><p>竞对：OpenAI与谷歌同类决策接口定价为0.1美元<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTMyOTI4Mw==&amp;chksm=faab242c76ac4fc83f83d84a46a44bd57cb9aa9926cf2017cea776c1a5e19a4d2925770f1ec4&amp;idx=2&amp;mid=2247784424&amp;sn=086ec62a80bfafa2e557406aac1dc5dd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="自变量发布机器人模型-wall-oss-1-0" tabindex="-1"><a class="header-anchor" href="#自变量发布机器人模型-wall-oss-1-0"><span>自变量发布机器人模型 WALL-OSS-1.0</span></a></h3><p>机器人创企自变量发布具身模型 WALL-OSS-1.0 与接口。模型将语言、视觉与动作统一预训练，在真机测试中取得 55.1% 零样本成功率，已开放 API 申请。</p><p>物流分拣微调数据量从超千小时压缩至 10 小时</p><p>Nano 版单张 GPU 可带 18 台机器人</p><p>未经微调的桌面真机得分比 π0.5 高 70.8%<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=851759d26bb06c4fb841572b136efb56fe0fd67f5009c6dc3c0e4d70f2ee4026ffff9f245baa&amp;idx=1&amp;mid=2651076132&amp;sn=b275d89079bea4d585f24b284a83baa0" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="豆包个人智能体小豆公测-能代打电话" tabindex="-1"><a class="header-anchor" href="#豆包个人智能体小豆公测-能代打电话"><span>豆包个人智能体小豆公测：能代打电话</span></a></h3><p>豆包旗下个人智能体独立 App「小豆」开启邀请制公测，打通飞书与抖音生态，可替用户代打生活服务电话咨询预订，并主动读取短信推进待办。</p><p>电话服务：支持拨打商户问询包厢并留存录音与文字</p><p>应用联动：可提取飞书记录生成文档并发送到群聊</p><p>使用限制：定时任务限10个且每次拨打需手动确认<a href="https://mp.weixin.qq.com/s?__biz=MzIwNzc2NTk0NQ==&amp;chksm=961206148d20e9e4798fb258193e012f2bf7c54cfbd90219a32b6162d2d7822d0b94ec013201&amp;idx=1&amp;mid=2247623739&amp;sn=e790d9a3ae7ead26b1da3ca971e05b2b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="辛顿称大规模失业是ai巨头赚钱的副作用" tabindex="-1"><a class="header-anchor" href="#辛顿称大规模失业是ai巨头赚钱的副作用"><span>辛顿称大规模失业是AI巨头赚钱的副作用</span></a></h3><p>面对黄仁勋对风险言论的批评，辛顿正面回击，并直言大规模失业只是AI巨头追逐利润的副作用。他指出当前模型发展快于人类理解速度，而让 AI 变聪明与变善良是正交方向。</p><p>预测争端：2009年就曾指出做神经网络必须买英伟达芯片</p><p>黑盒理解：模型能力发展速度已超过人类对内部机制的理解速度</p><p>超级智能：若实现递归自我改进，首要道德指令应是善待人类<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=facffab06d9877d07f4503a7f6ac6dca816b93b1c6f15836b18828f53b386c2315b416f0329b&amp;idx=1&amp;mid=2247669731&amp;sn=d47717e0d2bde827c184e47fc33f5e0b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="a16z测万次ai购物-推荐重合度达73" tabindex="-1"><a class="header-anchor" href="#a16z测万次ai购物-推荐重合度达73"><span>a16z测万次AI购物：推荐重合度达73%</span></a></h3><p>a16z 对四款 Agent 完成 11307 次测试，发现不同AI首选商品完全一致的比例近四分之一。AI 浏览候选极少，且精于比对运费、退货和续费等隐性成本。</p><p>渠道流向：超半数消费支出仍流向Expedia等传统聚合平台</p><p>决策倾向：同价时86%选退货更好商家，青睐访客结账</p><p>渠道偏好：Grok和Muse分别明显偏向亚马逊与沃尔玛<a href="https://mp.weixin.qq.com/s?__biz=MzkyNTY1MjE2OA==&amp;chksm=c089e4930f8986a1035e8c3e4cc0c0ffa1f98345bffeba8a53252734194c19a676a894b81283&amp;idx=1&amp;mid=2247494734&amp;sn=beca2cd76fdc12886b4cdeb358b090cf" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="英伟达开源20亿参数车端驾驶模型" tabindex="-1"><a class="header-anchor" href="#英伟达开源20亿参数车端驾驶模型"><span>英伟达开源20亿参数车端驾驶模型</span></a></h3><p>清华、港大与英伟达等在 CoRL 研讨会上探讨自动驾驶世界模型落地。英伟达现场开源了20亿参数车端模型 Alpamayo 2 Edge，可在车端达约 10 帧每秒。</p><p>港大方案：构造对抗场景后训练，碰撞率下降超45%</p><p>语言用于最难的1%长尾与读路牌，动作交由世界模型</p><p>赵昊提出整合多视角视频与占据网格的模型OmniNWM<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=9153642c8a96d7fa69c95e5a59578c6d592e245d02428277368593cbe11a86b6a07cd9d4641c&amp;idx=2&amp;mid=2247749930&amp;sn=133a08ac8981744a819fe7a144616435" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯开源王者荣耀游戏翻译工具链" tabindex="-1"><a class="header-anchor" href="#腾讯开源王者荣耀游戏翻译工具链"><span>腾讯开源王者荣耀游戏翻译工具链</span></a></h3><p>腾讯开源游戏本地化工具链 TiMiHOKGameTranslator，配套支持 102 种语言的混元 Hy-MT3 模型；LlamaIndex 同步推出 8.1M 参数的纯 CPU 文档解析方案。</p><p>游戏套件：解决标签错乱与超框问题，对接版本管理</p><p>MT3模型：开源 1.8B、7B 及 30B MoE 三档规格</p><p>文档解析：纯 CPU 运行，可还原表格版式并输出 Markdown<a href="https://mp.weixin.qq.com/s?__biz=MzAxMjc3MjkyMg==&amp;chksm=8238486158d3115f8d6d1b568ef858debca8fe5c002ac6b689de33ecaa64c99eeeaf657e1149&amp;idx=1&amp;mid=2648435283&amp;sn=b517df6974206401bb535437dac17097" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek-开源-super-agent-架构原型" tabindex="-1"><a class="header-anchor" href="#deepseek-开源-super-agent-架构原型"><span>DeepSeek 开源 Super-agent 架构原型</span></a></h3><p>DeepSeek Harness 团队开源了智能体架构原型 DSH Super-agent，通过双层分工支持多端协同与全双工交互，目前处于实验验证阶段。</p><p>全双工异步执行，后台跑任务时用户可随时插话</p><p>Router 仅负责对接分发，具体设计与执行全交 Worker</p><p>计算与持久状态解耦，本机合盖断网云端仍可接续<a href="https://mp.weixin.qq.com/s?__biz=MzIzOTU0NTQ0MA==&amp;chksm=e8e2160e90dbbba1494793563380572e2ece90d7b55bb860b51a834d1ebf14204c500497e30a&amp;idx=1&amp;mid=2247562800&amp;sn=dfde8934e08bc1d8bad6e28f1a906287" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="百度开源2800亿参数文心5-5-flash" tabindex="-1"><a class="header-anchor" href="#百度开源2800亿参数文心5-5-flash"><span>百度开源2800亿参数文心5.5 Flash</span></a></h3><p>百度按 Apache 2.0 协议开源文心 5.5 Flash Preview。模型总参数量 2800 亿、激活 140 亿，支持最长 100 万 Token 上下文。</p><p>部署适配：支持 vLLM 与 SGLang 推理框架</p><p>评测表现：WebDev 榜位列开源模型第二</p><p>获取途径：模型权重已上线 HF 与魔搭社区<a href="https://mp.weixin.qq.com/s?__biz=MzI5NzUyMzM1Mg==&amp;chksm=edb1a74d62bc6cde1292954f0a661e18dd96a04e0534558ccf5d047e1707731539d59ea68d63&amp;idx=1&amp;mid=2247670791&amp;sn=7ec35a2402ec151add53ce2b33a3ea4f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="蚂蚁oceanbase开源ai数据库oceanseek" tabindex="-1"><a class="header-anchor" href="#蚂蚁oceanbase开源ai数据库oceanseek"><span>蚂蚁OceanBase开源AI数据库OceanSeek</span></a></h3><p>蚂蚁旗下数据库OceanBase发布湖库一体AI平台OceanLake，并向全球开源其核心引擎AI数据库OceanSeek。此外，官方披露其AI业务收入已突破1亿元。</p><p>向量检索：亿级向量测试吞吐最高约为ES的17.3倍</p><p>本体构建：推出平台Ontoss使本体构建效率提升10倍</p><p>应用进展：已在线下多模态场景落地且即将上线云端版本<a href="https://mp.weixin.qq.com/s?__biz=MzA4MTQ4NjQzMw==&amp;chksm=859df14177abeff9945386338c1d8390930db7779a4779a26bd1601642264b52ba79bf123d44&amp;idx=2&amp;mid=2652814894&amp;sn=17cf2f3ad6ffb33bc4c67538520e8428" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="阿里达摩院开源机器人模型rynnvla" tabindex="-1"><a class="header-anchor" href="#阿里达摩院开源机器人模型rynnvla"><span>阿里达摩院开源机器人模型RynnVLA</span></a></h3><p>阿里达摩院等开源具身智能模型 RynnVLA-Latent，把 3.01万小时 异构视频提取为潜在动作来预训练机器人，已在六项双臂真机任务中取得最高成功率。</p><p>汇集25个视频源共30.57亿帧，提取超7亿个动作描述符</p><p>4B模型在LIBERO基准仿真任务中成功率达到98.8%</p><p>论文与模型代码已同步上线GitHub和魔搭社区<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9030c59f5864c1ea316258192b5fed5ad1ee4c0cd8486140d7a45e03c95e85faccafa6232e6&amp;idx=3&amp;mid=2247948323&amp;sn=f554a3311a9945f2a61b4c13d2f3313c" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="开源推理引擎-rsinfer-秒级热更新" tabindex="-1"><a class="header-anchor" href="#开源推理引擎-rsinfer-秒级热更新"><span>开源推理引擎 RSInfer，秒级热更新</span></a></h3><p>港科大王威团队与阿里开源推理引擎 RSInfer，将代码与显存状态解耦，实现秒级多卡在线热更新，避免 AI Agent 调优时数十分钟的冷启动。</p><p>迭代速度：4卡475GB模型热更新仅需5秒</p><p>推理性能：吞吐超DeepInfer最高31.8%</p><p>开源情况：采用Apache 2.0协议<a href="https://mp.weixin.qq.com/s?__biz=MzA4MjY4NTk0NQ==&amp;chksm=9ec2e464b7cc1230db66e452bd9157d75921b197dee1dc9bab31698229ecb1271b79c058fea7&amp;idx=1&amp;mid=2247532925&amp;sn=71f0b8683c428c33d12980e41bd2c4a1" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="google提sim让agent跨模型自改进" tabindex="-1"><a class="header-anchor" href="#google提sim让agent跨模型自改进"><span>Google提SIM让Agent跨模型自改进</span></a></h3><p>Google团队提出自我改进记忆机制SIM，记录Agent外围控制程序的修改理由与实测结果，在编码测试中使跨任务续跑平均得分高出2.36分。</p><p>机制：保存修改意图与评估背景供优化器复用</p><p>跨模型效果：Opus优化的程序迁移至Gemini后达84.75分</p><p>局限：依赖接口兼容且存在个别性能回退案例<a href="https://mp.weixin.qq.com/s?__biz=MzUxNjcxMjQxNg==&amp;chksm=f8db37620a61a8c906d32feee3225b18ea281625d12ec877c544de0b0b8001469d0384cf75c4&amp;idx=3&amp;mid=2247645320&amp;sn=cef56e7aaafddf1d01334865ff90fb2f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepmind用ai优化量子算法降低成本290倍" tabindex="-1"><a class="header-anchor" href="#deepmind用ai优化量子算法降低成本290倍"><span>DeepMind用AI优化量子算法降低成本290倍</span></a></h3><p>DeepMind 用 Gemini 团队优化核聚变、药物代谢量子算法，通过 Lean 完成验证，基础算术模块时空成本最高降低约290倍。</p><p>科学模拟：核聚变模拟成本降11.8倍</p><p>药物研发：P450酶模拟成本降2.49倍</p><p>开源情况：开放量子计算Lean形式化库和验证后算法代码<a href="https://mp.weixin.qq.com/s?__biz=MzI3MjM3ODk0NQ==&amp;chksm=ea6a0cbd11b3708e780fd6b54852285657f2d4f5e2b3dc77529cb866e6a5779419621a178eb0&amp;idx=1&amp;mid=2247514505&amp;sn=a33aac37169bbcfead6c990287c9fe02" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',109)]))}const l=a(r,[["render",d]]),t=JSON.parse('{"path":"/posts/2026-11-25.html","title":"AI日报：OpenAI首席科学家公布模型困惑度; MiniMax模型破译密码速度提升4万倍; 马斯克称 Optimus 18 个月内能洗碗","lang":"zh-CN","frontmatter":{"date":"2026-11-25T00:00:00.000Z","title":"AI日报：OpenAI首席科学家公布模型困惑度; MiniMax模型破译密码速度提升4万倍; 马斯克称 Optimus 18 个月内能洗碗"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"OpenAI首席科学家公布模型困惑度","slug":"openai首席科学家公布模型困惑度","link":"#openai首席科学家公布模型困惑度","children":[]},{"level":3,"title":"MiniMax模型破译密码速度提升4万倍","slug":"minimax模型破译密码速度提升4万倍","link":"#minimax模型破译密码速度提升4万倍","children":[]},{"level":3,"title":"马斯克称 Optimus 18 个月内能洗碗","slug":"马斯克称-optimus-18-个月内能洗碗","link":"#马斯克称-optimus-18-个月内能洗碗","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"Sand.ai发布MAGI-2：1080P每秒0.5元","slug":"sand-ai发布magi-2-1080p每秒0-5元","link":"#sand-ai发布magi-2-1080p每秒0-5元","children":[]},{"level":3,"title":"小鹏发布X-World 1.6世界模型","slug":"小鹏发布x-world-1-6世界模型","link":"#小鹏发布x-world-1-6世界模型","children":[]},{"level":3,"title":"Anthropic更新MCP支持技能与长任务","slug":"anthropic更新mcp支持技能与长任务","link":"#anthropic更新mcp支持技能与长任务","children":[]},{"level":3,"title":"Snowflake推决策AI：百万Token 4.2美分","slug":"snowflake推决策ai-百万token-4-2美分","link":"#snowflake推决策ai-百万token-4-2美分","children":[]},{"level":3,"title":"自变量发布机器人模型 WALL-OSS-1.0","slug":"自变量发布机器人模型-wall-oss-1-0","link":"#自变量发布机器人模型-wall-oss-1-0","children":[]},{"level":3,"title":"豆包个人智能体小豆公测：能代打电话","slug":"豆包个人智能体小豆公测-能代打电话","link":"#豆包个人智能体小豆公测-能代打电话","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"辛顿称大规模失业是AI巨头赚钱的副作用","slug":"辛顿称大规模失业是ai巨头赚钱的副作用","link":"#辛顿称大规模失业是ai巨头赚钱的副作用","children":[]},{"level":3,"title":"a16z测万次AI购物：推荐重合度达73%","slug":"a16z测万次ai购物-推荐重合度达73","link":"#a16z测万次ai购物-推荐重合度达73","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"英伟达开源20亿参数车端驾驶模型","slug":"英伟达开源20亿参数车端驾驶模型","link":"#英伟达开源20亿参数车端驾驶模型","children":[]},{"level":3,"title":"腾讯开源王者荣耀游戏翻译工具链","slug":"腾讯开源王者荣耀游戏翻译工具链","link":"#腾讯开源王者荣耀游戏翻译工具链","children":[]},{"level":3,"title":"DeepSeek 开源 Super-agent 架构原型","slug":"deepseek-开源-super-agent-架构原型","link":"#deepseek-开源-super-agent-架构原型","children":[]},{"level":3,"title":"百度开源2800亿参数文心5.5 Flash","slug":"百度开源2800亿参数文心5-5-flash","link":"#百度开源2800亿参数文心5-5-flash","children":[]},{"level":3,"title":"蚂蚁OceanBase开源AI数据库OceanSeek","slug":"蚂蚁oceanbase开源ai数据库oceanseek","link":"#蚂蚁oceanbase开源ai数据库oceanseek","children":[]},{"level":3,"title":"阿里达摩院开源机器人模型RynnVLA","slug":"阿里达摩院开源机器人模型rynnvla","link":"#阿里达摩院开源机器人模型rynnvla","children":[]},{"level":3,"title":"开源推理引擎 RSInfer，秒级热更新","slug":"开源推理引擎-rsinfer-秒级热更新","link":"#开源推理引擎-rsinfer-秒级热更新","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"Google提SIM让Agent跨模型自改进","slug":"google提sim让agent跨模型自改进","link":"#google提sim让agent跨模型自改进","children":[]},{"level":3,"title":"DeepMind用AI优化量子算法降低成本290倍","slug":"deepmind用ai优化量子算法降低成本290倍","link":"#deepmind用ai优化量子算法降低成本290倍","children":[]}]}],"git":{"updatedTime":1795699860000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"75c02e202124d34405475b6f6f15a6fddb8541f1","time":1795699860000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-26T13:31:00.952Z"}]},"filePathRelative":"posts/2026-11-25.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-25 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>OpenAI首席科学家公布模型困惑度</h3>\\n<p>OpenAI 首席科学家公开核心指标困惑度，透露 GPT-3.5 约为 0.99、GPT-4 约为 0.91，最新模型已低于 0.8。</p>\\n<p>建议全行业据此设上限，达安全监控标准再推进</p>"}');export{l as comp,t as data};
